  c jsonb; t record; current_row record; actual text; changed integer; total integer := 0;
BEGIN
  IF jsonb_array_length(changes) <> 18 OR
     (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(changes) x) <> 18 THEN
    RAISE EXCEPTION 'PC-J174: invalid patch membership';
  END IF;
  -- Canonical lock order matches source triggers; parent first, then questions.
  FOR t IN SELECT DISTINCT x->>'test_uuid' id FROM jsonb_array_elements(changes) x ORDER BY id LOOP
    PERFORM public.fn_lock_mock_paper('reading',t.id::uuid);
    PERFORM 1 FROM public.reading_tests WHERE id=t.id::uuid FOR UPDATE;
  END LOOP;
  -- Hold passage membership stable and prevent source drift until commit.
  PERFORM 1 FROM public.reading_passages p WHERE p.id IN
    (SELECT (x->>'passage_id')::uuid FROM jsonb_array_elements(changes) x) ORDER BY p.id FOR SHARE;
  PERFORM 1 FROM public.reading_questions q WHERE q.id IN
    (SELECT (x->>'id')::uuid FROM jsonb_array_elements(changes) x
     UNION SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(changes) x) ORDER BY q.id FOR UPDATE;
  -- Validate ALL rows before the first UPDATE. Full content hashes include
  -- answer, explanation and skill metadata; only timestamps are excluded.
  FOR c IN SELECT value FROM jsonb_array_elements(changes) LOOP
    SELECT rq.*, md5((to_jsonb(rq)-'updated_at'-'created_at')::text) digest INTO current_row
      FROM public.reading_questions rq
      JOIN public.reading_passages p ON p.id=rq.passage_id
      JOIN public.reading_tests rt ON rt.id=p.test_id
      WHERE rq.id=(c->>'id')::uuid AND rq.passage_id=(c->>'passage_id')::uuid
        AND rq.q_num=(c->>'q_num')::integer AND rt.id=(c->>'test_uuid')::uuid
        AND rt.test_id=c->>'test_id' AND rt.status='draft'
        AND rt.is_public IS FALSE AND rt.exam_only IS TRUE
        AND rt.policy_revision=(c->>'policy_revision')::bigint;
    IF NOT FOUND THEN RAISE EXCEPTION 'PC-J174: identity/draft/policy drift at %',c->>'id'; END IF;
    IF current_row.digest IS DISTINCT FROM c->>'after_md5' THEN
      RAISE EXCEPTION 'PC-J174: rollback md5 precondition failed at %, expected %, actual %',c->>'id',c->>'after_md5',current_row.digest;
    END IF;
  END LOOP;
  FOR c IN SELECT value FROM jsonb_array_elements(changes) LOOP
    UPDATE public.reading_questions SET question_type=c->'desired'->>'question_type',
      prompt=c->'desired'->>'prompt',payload=c->'desired'->'payload' WHERE id=(c->>'id')::uuid;
    GET DIAGNOSTICS changed = ROW_COUNT;
    IF changed <> 1 THEN RAISE EXCEPTION 'PC-J174: row count failed at %',c->>'id'; END IF;
    total:=total+changed;
    SELECT md5((to_jsonb(rq)-'updated_at'-'created_at')::text) INTO actual
      FROM public.reading_questions rq WHERE id=(c->>'id')::uuid;
    IF actual IS DISTINCT FROM c->>'before_md5' THEN
      RAISE EXCEPTION 'PC-J174: rollback readback failed at %',c->>'id';
    END IF;
  END LOOP;
  IF total <> 18 THEN RAISE EXCEPTION 'PC-J174: expected 18 changes, got %',total; END IF;
  RAISE NOTICE 'PC-J174 ROLLBACK PASS: 18 questions, 4 draft papers';
END $pcj174$;
COMMIT;
